package com.acxiom.crm.api; import com.acxiom.crm.followup.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/followups") public class FollowUpApiController {private final FollowUpRepository repo; public FollowUpApiController(FollowUpRepository r){repo=r;} @GetMapping public List<FollowUp> all(){return repo.findAll();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public FollowUp create(@Valid @RequestBody FollowUp f){if(f.getFollowUpDate()!=null&&f.getFollowUpDate().isBefore(LocalDate.now())&&"Planned".equals(f.getStatus()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Planned follow-up cannot be in the past");return repo.save(f);} }
